// Generated by `npm run avatars:likeness:publish`; only human-approved kits.
import loadable from '../../../../data/avatars/likeness/loadable.json';

export type LoadableHeadKit = {
  candidateId: string;
  slug: string;
  path: string;
};

/**
 * Build-time view of the human-approved head kits. `data/avatars/likeness/loadable.json` is derived by
 * `npm run avatars:likeness:publish` from the generated manifest plus the
 * hand-authored review file; only kits a reviewer approved appear here.
 * Everything else keeps the shared base avatar, so this map is deliberately
 * allowed to be tiny (or empty).
 */
const kits = loadable.kits as LoadableHeadKit[];

const bySlug = new Map(kits.map((kit) => [kit.slug, kit] as const));

export const approvedHeadKitCount = kits.length;

export function headKitForSlug(slug: string): LoadableHeadKit | undefined {
  return bySlug.get(slug);
}
